class Solution {
public:
    int minMaxWeight(int n, vector<vector<int>>& edges, int threshold) {
        vector<vector<pair<int, int>>> revGraph(n);
        int maxW = 0;
        for (const auto& e : edges) {
            revGraph[e[1]].push_back({e[0], e[2]});
            maxW = max(maxW, e[2]);
        }

        auto canReachAll = [&](int limit) -> bool {
            vector<bool> seen(n, false);
            vector<int> st = {0};
            seen[0] = true;
            int count = 1;
            while (!st.empty()) {
                int u = st.back();
                st.pop_back();
                for (const auto& [v, w] : revGraph[u]) {
                    if (!seen[v] && w <= limit) {
                        seen[v] = true;
                        count++;
                        st.push_back(v);
                    }
                }
            }
            return count == n;
        };

        int low = 1, high = maxW, ans = -1;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (canReachAll(mid)) {
                ans = mid;
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }
        return ans;
    }
};

class Solution {
    public int minMaxWeight(int n, int[][] edges, int threshold) {
        List<int[]>[] revGraph = new ArrayList[n];
        for (int i = 0; i < n; ++i) revGraph[i] = new ArrayList<>();
        int maxW = 0;
        for (int[] e : edges) {
            revGraph[e[1]].add(new int[]{e[0], e[2]});
            maxW = Math.max(maxW, e[2]);
        }

        int low = 1, high = maxW, ans = -1;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (canReachAll(n, revGraph, mid)) {
                ans = mid;
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }
        return ans;
    }

    private boolean canReachAll(int n, List<int[]>[] revGraph, int limit) {
        boolean[] seen = new boolean[n];
        Deque<Integer> st = new ArrayDeque<>();
        st.push(0);
        seen[0] = true;
        int count = 1;
        while (!st.isEmpty()) {
            int u = st.pop();
            for (int[] edge : revGraph[u]) {
                int v = edge[0], w = edge[1];
                if (!seen[v] && w <= limit) {
                    seen[v] = true;
                    count++;
                    st.push(v);
                }
            }
        }
        return count == n;
    }
}

var minMaxWeight = function(n, edges, threshold) {
    const revGraph = Array.from({ length: n }, () => []);
    let maxW = 0;
    for (const [u, v, w] of edges) {
        revGraph[v].push([u, w]);
        if (w > maxW) maxW = w;
    }

    const canReachAll = (limit) => {
        const seen = new Uint8Array(n);
        const st = [0];
        seen[0] = 1;
        let count = 1;
        while (st.length > 0) {
            const u = st.pop();
            for (const [v, w] of revGraph[u]) {
                if (!seen[v] && w <= limit) {
                    seen[v] = 1;
                    count++;
                    st.push(v);
                }
            }
        }
        return count === n;
    };

    let low = 1, high = maxW, ans = -1;
    while (low <= high) {
        const mid = (low + high) >> 1;
        if (canReachAll(mid)) {
            ans = mid;
            high = mid - 1;
        } else {
            low = mid + 1;
        }
    }
    return ans;
};
